package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen2Test {



    @Test
    public void testToClass_WithValidObjects() {
        Object[] input = { "string", 123, 45.67, Boolean.TRUE };
        Class<?>[] expected = { String.class, Integer.class, Double.class, Boolean.class };
        Class<?>[] actual = ClassUtils.toClass(input);

        Assert.assertNotNull(actual);
        Assert.assertEquals(expected.length, actual.length);
        for (int i = 0; i < expected.length; i++) {
            Assert.assertEquals("Mismatch at index " + i, expected[i], actual[i]);
        }
    }




}

package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen2Test {





    @Test
    public void testToClass_WithNullElements() {
        Object[] input = { "string", null, 123 };
        Class<?>[] expected = { String.class, null, Integer.class };
        Class<?>[] actual = ClassUtils.toClass(input);

        Assert.assertNotNull(actual);
        Assert.assertEquals(expected.length, actual.length);
        Assert.assertEquals(expected[0], actual[0]);
        Assert.assertNull("Element at index 1 should be null", actual[1]);
        Assert.assertEquals(expected[2], actual[2]);
    }


}

